pm.test("Status code is 201 Created", function () {
    pm.response.to.have.status(201);
});

pm.test("Response is JSON", function () {
    pm.response.to.be.json;
});

const json = pm.response.json();

pm.test("Response contains correct email", function () {
    pm.expect(json.email).to.eql(pm.collectionVariables.get("testEmail"));
});

pm.test("Response contains correct full name", function () {
    pm.expect(json.fullName).to.eql("Test User");
});

pm.test("New users are assigned User role", function () {
    pm.expect(json.role).to.eql("User");
});

pm.test("Response contains createdDate", function () {
    pm.expect(json.createdDate).to.exist;
});

pm.test("Password hash is not exposed", function () {
    pm.expect(json).to.not.have.property("passwordHash");
});

pm.test("Status code is 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("Response is JSON", function () {
    pm.response.to.be.json;
});

const json = pm.response.json();

pm.test("Response contains JWT", function () {
    pm.expect(json.token).to.exist;
    pm.expect(json.token).to.be.a("string");
    pm.expect(json.token.length).to.be.greaterThan(0);
});

pm.test("Response contains expiry", function () {
    pm.expect(json.expires).to.exist;
});

pm.test("Response contains user information", function () {
    pm.expect(json.user).to.exist;
    pm.expect(json.user.email).to.exist;
    pm.expect(json.user.fullName).to.exist;
    pm.expect(json.user.role).to.exist;
});

pm.test("Correct user was authenticated", function () {
    pm.expect(json.user.email)
        .to.eql(pm.collectionVariables.get("testEmail"));

    pm.expect(json.user.fullName)
        .to.eql("Test User");

    pm.expect(json.user.role)
        .to.eql("User");
});


//save token for future requests
if (pm.response.code === 200) {
    const json = pm.response.json();

    pm.collectionVariables.set(
        "authToken",
        json.token
    );
}

pm.test("Status code is 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("Response is JSON", function () {
    pm.response.to.be.json;
});

const json = pm.response.json();

pm.test("Response contains exactly 5 forecasts", function () {
    pm.expect(json).to.be.an("array");
    pm.expect(json.length).to.eql(5);
});

pm.test("Each forecast contains the required properties", function () {
    json.forEach(function (forecast) {
        pm.expect(forecast).to.have.property("date");
        pm.expect(forecast).to.have.property("temperatureC");
        pm.expect(forecast).to.have.property("summary");
    });
});

pm.test("Temperatures are within the expected range", function () {
    json.forEach(function (forecast) {
        pm.expect(forecast.temperatureC).to.be.at.least(-20);
        pm.expect(forecast.temperatureC).to.be.below(55);
    });
});

pm.test("Summaries contain valid values", function () {
    const validSummaries = [
        "Freezing",
        "Bracing",
        "Chilly",
        "Cool",
        "Mild",
        "Warm",
        "Balmy",
        "Hot",
        "Sweltering",
        "Scorching"
    ];

    json.forEach(function (forecast) {
        pm.expect(validSummaries).to.include(forecast.summary);
    });
});
